"""Comparison sentences generated by a pre-registered claim rule, never written by hand.

For arms a and b, a metric (lower is better), a condition and a trajectory:

1. Pair episodes by (training seed, evaluation seed) - common random numbers: both
   arms face the same initial state and the same sampled disturbance.
2. Hierarchical bootstrap of the mean paired difference (10,000 resamples): resample
   training seeds with replacement, then episodes within each drawn seed.
3. "a is better than b" is claimed only if the 95% interval excludes 0, the winner's
   termination rate is not higher than the loser's, and every planned training seed
   of both arms was evaluated. Otherwise the sentence is "no decidable difference".

    python -m residual_rl.claims                    # reads results/eval.csv.gz
"""

from __future__ import annotations

import argparse
import csv
import gzip
import json
from pathlib import Path

import numpy as np

RESAMPLES, RNG_SEED, CI = 10_000, 0, 0.95
TRAIN_SEEDS = tuple(range(5))
METRICS = ("e_rms", "e_rms_ss", "e_max", "terminated")
ARMS = ("joint_pd", "impedance", "residual@500k", "residual@1M", "direct@500k", "direct@1M")
CONDITIONS, TRAJECTORIES = ("C0", "C1", "C2", "C3"), ("T1", "T2")
COMPARISONS = (("residual@1M", "impedance"), ("direct@1M", "impedance"), ("residual@1M", "direct@1M"),
               ("residual@500k", "residual@1M"), ("direct@500k", "direct@1M"))


def arm_of(method: str, checkpoint: str) -> str:
    return method if checkpoint == "na" else f"{method}@{checkpoint}"


def load(path: Path) -> dict:
    """{(arm, cond, traj): {metric: {(seed, episode): value}}}; baselines carry seed -1."""
    data: dict = {}
    with gzip.open(path, "rt", newline="", encoding="utf-8") as f:
        for d in csv.DictReader(f):
            cell = data.setdefault((arm_of(d["method"], d["checkpoint"]), d["condition"], d["trajectory"]),
                                   {m: {} for m in METRICS})
            for m in METRICS:
                v = d[m]
                cell[m][(int(d["seed"]), int(d["episode"]))] = float(v) if v not in ("", "nan") else float("nan")
    return data


def matrix(values: dict) -> np.ndarray:
    """(seeds x episodes) array over the episodes every seed has."""
    seeds = sorted({s for s, _ in values})
    eps = sorted(set.intersection(*[{e for s2, e in values if s2 == s} for s in seeds]))
    return np.array([[values[(s, e)] for e in eps] for s in seeds], dtype=float)


def hboot(X: np.ndarray, rng) -> np.ndarray:
    S, E = X.shape
    si = rng.integers(0, S, size=(RESAMPLES, S))
    ei = rng.integers(0, E, size=(RESAMPLES, S, E))
    return X[si[:, :, None], ei].mean(axis=(1, 2))


def paired(data, a, b, cond, traj, metric):
    A, B = data[(a, cond, traj)][metric], data[(b, cond, traj)][metric]
    TA, TB = data[(a, cond, traj)]["terminated"], data[(b, cond, traj)]["terminated"]
    a_base, b_base = {s for s, _ in A} == {-1}, {s for s, _ in B} == {-1}
    if b_base and not a_base:  # a baseline is deterministic in the seed: pair on the episode
        keys = {(s, e) for s, e in A if (-1, e) in B}
        ak, bk = {k: k for k in keys}, {k: (-1, k[1]) for k in keys}
    elif a_base and not b_base:
        keys = {(s, e) for s, e in B if (-1, e) in A}
        ak, bk = {k: (-1, k[1]) for k in keys}, {k: k for k in keys}
    else:
        keys = set(A) & set(B)
        ak = bk = {k: k for k in keys}
    D = matrix({k: A[ak[k]] - B[bk[k]] for k in keys})
    return D, float(np.mean([TA[ak[k]] for k in keys])), float(np.mean([TB[bk[k]] for k in keys]))


def complete(data, arm, cond, traj) -> bool:
    seeds = sorted({s for s, _ in data[(arm, cond, traj)]["e_rms"]})
    return seeds == [-1] if "@" not in arm else seeds == list(TRAIN_SEEDS)


def decide(lo, hi, ta, tb, all_seeds):
    winner = "a" if hi < 0 else "b" if lo > 0 else None
    if winner is None or not all_seeds:
        return winner, False
    return winner, (ta <= tb) if winner == "a" else (tb <= ta)


def sentence(a, b, metric, cond, traj, winner, resolved) -> str:
    if resolved:
        w, l = (a, b) if winner == "a" else (b, a)
        return f"{w} better than {l} ({metric}, {cond}/{traj})"
    return f"no decidable difference between {a} and {b} ({metric}, {cond}/{traj})"


def summarise(data) -> dict:
    rng = np.random.default_rng(RNG_SEED)
    q = [100 * (1 - CI) / 2, 100 * (1 + CI) / 2]
    groups = {}
    for arm in ARMS:
        for cond in CONDITIONS:
            for traj in TRAJECTORIES:
                for m in METRICS:
                    X = matrix(data[(arm, cond, traj)][m])
                    lo, hi = np.percentile(hboot(X, rng), q)
                    groups.setdefault(arm, {}).setdefault(cond, {}).setdefault(traj, {})[m] = {
                        "mean": float(X.mean()), "ci": [float(lo), float(hi)], "n_seeds": X.shape[0]}
    comps = []
    for a, b in COMPARISONS:
        for m in METRICS:
            for cond in CONDITIONS:
                for traj in TRAJECTORIES:
                    D, ta, tb = paired(data, a, b, cond, traj, m)
                    lo, hi = np.percentile(hboot(D, rng), q)
                    all_seeds = complete(data, a, cond, traj) and complete(data, b, cond, traj)
                    winner, resolved = decide(float(lo), float(hi), ta, tb, all_seeds)
                    comps.append({"a": a, "b": b, "metric": m, "condition": cond, "trajectory": traj,
                                  "mean_diff": float(D.mean()), "ci": [float(lo), float(hi)],
                                  "term_rate_a": ta, "term_rate_b": tb, "resolved": resolved,
                                  "sentence": sentence(a, b, m, cond, traj, winner, resolved)})
    return {"groups": groups, "comparisons": comps}


def main() -> None:
    ap = argparse.ArgumentParser()
    root = Path(__file__).resolve().parents[1]
    ap.add_argument("--eval", type=Path, default=root / "results" / "eval.csv.gz")
    ap.add_argument("--out", type=Path, default=root / "results" / "claims.json")
    args = ap.parse_args()
    s = summarise(load(args.eval))
    args.out.write_text(json.dumps(s, indent=1))
    for c in s["comparisons"]:
        if c["metric"] == "e_rms_ss" and (c["a"], c["b"]) == ("residual@1M", "impedance"):
            print(f"{c['sentence']:70s} diff {c['mean_diff']:+.4f} [{c['ci'][0]:+.4f}, {c['ci'][1]:+.4f}]")


if __name__ == "__main__":
    main()
